/// Execute activate transition on a TemporaryPermission.
///
/// POST /temporary_permissions/:id/transitions/activate
pub async fn activate_transition(
    axum::extract::State(service): axum::extract::State<Arc<TemporaryPermissionService>>,
    axum::extract::Path(id): axum::extract::Path<String>,
    auth: Option<axum::Extension<AuthContext>>,
) -> impl axum::response::IntoResponse {
    use axum::{http::StatusCode, Json};

    // Get current entity
    let entity = match service.get_by_id(&id).await {
        Ok(Some(e)) => e,
        Ok(None) => return (StatusCode::NOT_FOUND, Json(ApiResponse::<TemporaryPermissionResponseDto>::not_found("TemporaryPermission", &id))),
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, Json(ApiResponse::<TemporaryPermissionResponseDto>::error(e.to_string()))),
    };

    // Check permission
    let Some(axum::Extension(auth)) = auth else {
        return (StatusCode::UNAUTHORIZED, Json(ApiResponse::<TemporaryPermissionResponseDto>::error("A transition needs an authenticated caller")));
    };
    {
        let allowed_roles = TemporaryPermissionTransition::Activate.allowed_roles();
        let granted = |required: &str| auth.permissions.iter().any(|p| {
            let (have, want): (Vec<&str>, Vec<&str>) = (p.split(':').collect(), required.split(':').collect());
            have.iter().enumerate().all(|(i, h)| *h == "*" || want.get(i) == Some(h))
                && (have.len() == want.len() || (have.len() < want.len() && have.last() == Some(&"*")))
        });
        let has_specific_perm = granted("temporary_permission:transition:activate");
        let has_role = auth.roles.iter().any(|r| allowed_roles.contains(&r.as_str()));
        if !has_specific_perm && !has_role {
            return (StatusCode::FORBIDDEN, Json(ApiResponse::<TemporaryPermissionResponseDto>::error("activate needs temporary_permission:transition:activate or one of the roles admin")));
        }
    }

    // Create state machine from entity's actual status and validate transition
    let current_state: TemporaryPermissionState = match entity.status.to_string().parse() {
        Ok(s) => s,
        Err(_) => return (StatusCode::CONFLICT, Json(ApiResponse::<TemporaryPermissionResponseDto>::error("The stored state is not a state of this machine"))),
    };
    let sm = TemporaryPermissionStateMachine::from_state(current_state);
    if !sm.can_transition(TemporaryPermissionTransition::Activate) {
        return (StatusCode::BAD_REQUEST, Json(ApiResponse::<TemporaryPermissionResponseDto>::error("Transition not allowed from current state")));
    }

    // Guard `effective_from == null || effective_from <= now()` not compiled (`effective_from` is not a field of TemporaryPermission); the transition is not checked against it.
    // Apply transition via partial update
    let mut fields: HashMap<String, serde_json::Value> = HashMap::new();
    fields.insert("status".to_string(), serde_json::Value::String("active".to_string()));

    match backbone_core::write_guard::as_transition("activate", service.partial_update(&id, fields)).await {
        Ok(Some(updated)) => {
            let response: TemporaryPermissionResponseDto = updated.into();
            (StatusCode::OK, Json(ApiResponse::ok(response)))
        }
        Ok(None) => (StatusCode::NOT_FOUND, Json(ApiResponse::<TemporaryPermissionResponseDto>::not_found("TemporaryPermission", &id))),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, Json(ApiResponse::<TemporaryPermissionResponseDto>::error(e.to_string()))),
    }
}

